&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, you’ll find an environment designed for continuous learning, meaningful impact, and professional growth. Whether you&#39;re pioneering new digital solutions, challenging conventional thinking or building the next generation of customer experiences, your work will help transform industries.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are proud of:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/work/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;The work we do and the innovation we drive&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/career/our-values/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Our values of share, care &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;a&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;nd dare&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/valtech-as-workplace/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;A workplace culture that fosters creativity, diversity and autonomy&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
